(5104679, 742194, 89341, '<td valign="top">nice focus and the selective desat works, I''m not so sure about the squint in her eyes</td>', 'nice focus and the selective desat works, I''m not so sure about the squint in her eyes', '2008-12-04 07:53:11.000000', NULL, 1),
(5104680, 739428, 27161, '<td valign="top">I really like this photo, but I think the sky is oversaturated with yellow. 7</td>', 'I really like this photo, but I think the sky is oversaturated with yellow. 7', '2008-12-04 07:53:24.000000', NULL, 1),
(5104681, 743603, 27161, '<td valign="top">Nice and moody.  Very interesting to look at. I don''t know of any photos like it. 10</td>', 'Nice and moody.  Very interesting to look at. I don''t know of any photos like it. 10', '2008-12-04 07:54:54.000000', NULL, 1),
