INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5111008, 742856, 76335, '<td valign="top">Nice low key portrait. Very honest and a good character study.</td>', 'Nice low key portrait. Very honest and a good character study.', '2008-12-05 23:30:29.000000', NULL, 1),
(5111009, 739873, 76335, '<td valign="top">Excellent depth, lots to look at. Nice!</td>', 'Excellent depth, lots to look at. Nice!', '2008-12-05 23:30:33.000000', NULL, 1),
(5111010, 743043, 76335, '<td valign="top">Beautiful portrait. One to frame. (Validated?)</td>', 'Beautiful portrait. One to frame. (Validated?)', '2008-12-05 23:30:35.000000', NULL, 1),
(5111011, 736132, 76335, '<td valign="top">I like the icy textures and cool tones. Well done.</td>', 'I like the icy textures and cool tones. Well done.', '2008-12-05 23:30:37.000000', NULL, 1),
(5111012, 738215, 76335, '<td valign="top">Artistic and very imaginitive. Great processing.</td>', 'Artistic and very imaginitive. Great processing.', '2008-12-05 23:30:41.000000', NULL, 1),
